// zh-tw message catalog, typed `Partial<Record<MessageId, string>>`:
// an id it lacks renders the English until it is translated (backfilled in
// batches; docs/frontend/i18n/README.md), and an id en no longer has is a
// compile error.
//
// Terms and style: docs/frontend/i18n/zh-tw.md. Traditional Chinese as used
// in Taiwan, written from the zh-cn reading of each string; Agent and brand
// forms (Raft, Raft Computer, …) stay Latin. Chinese has no count-plural
// distinction, so plural ICU uses a single `other` arm.

import type { MessageId } from "./en";

