  "migration.error.entryCountLimitExceeded": "工作區中的檔案和資料夾太多，無法遷移。請讓 Agent 刪除不再需要的資料夾，或將它們列入 .raftmigrateignore，然後再試一次。",
  "migration.error.entryCountLimitExceededWithDetails": "工作區有 {count, number} 個檔案和資料夾，遷移最多支援 {limit, number} 個。{paths, select, none {} other {大部分位於：{paths}。}}請讓 Agent 刪除不再需要的資料夾，或將它們列入 .raftmigrateignore，然後再試一次。",
  "migration.error.workspaceAlreadyExists": "目標電腦無法安裝這個 Agent，因為該工作區已經存在。請確認哪一份是目前使用的副本，將衝突的工作區移走或備份，然後再試一次。Raft 不會自動刪除它。",
  "migration.error.workspaceCompleteOldCopy": "目標電腦發現這個工作區先前已完成的副本，因此在取代它之前就停止了。請確認哪一份是目前使用的副本，將舊副本移走或備份，然後再試一次。Raft 不會自動刪除它。",
  "migration.error.workspaceAlreadyExistsAt": "目標電腦上的 {path} 已有工作區，因此未安裝 Agent。請將該資料夾重新命名或移走（例如在名稱後加上 .bak 即可），然後重新開始遷移。移動前請先確認這不是你仍需要的副本——Raft 絕不會刪除它，移走後它仍會留在那台電腦上。",
  "migration.error.workspaceCompleteOldCopyAt": "目標電腦上的 {path} 是先前遷移留下的完整工作區副本，因此 Raft 沒有覆寫它，而是停止了遷移。請將該資料夾重新命名或移走（例如在名稱後加上 .old 即可），然後重新開始遷移。移動前請先確認哪一份是目前使用的副本——Raft 絕不會刪除它，移走後它仍會留在那台電腦上。",
  "migration.error.controlManifestInvalid": "來源電腦產生的傳輸中繼資料無法通過目標電腦的驗證。請更新兩台電腦上的 Raft Computer，然後再試一次。",
  "migration.error.refInvalid": "遷移編號遺失或無效。請先重新整理遷移狀態，然後再試一次。",
  "migration.error.revisionInvalid": "遷移狀態不完整。請重新整理後再嘗試取消。",
  "migration.error.notFound": "這次遷移已不存在。請重新整理遷移狀態。",
  "migration.error.revisionStale": "此操作完成前，遷移狀態已有變更。請重新整理後再試一次。",
  "migration.error.concurrentUpdate": "遷移狀態同時被其他操作更新。請重新整理後再試一次。",
  "migration.error.cancelFailed": "Raft 無法送出取消要求。請重新整理遷移狀態，然後再試一次。",
