  "migration.error.objectStoreUnreachable": "其中一台電腦連續 5 分鐘無法連上 Raft 的遷移儲存空間。請檢查該電腦的網路、代理伺服器或防火牆，然後再試一次。",
  "migration.error.computerOwnerDeleted": "這次遷移已停止：其中一台電腦的擁有者刪除了 Raft 帳號。請把這個 Agent 移到另一台電腦。",
  "migration.error.targetComputerDetached": "這次遷移已停止：目標電腦在 Agent 移入之前就已中斷連接。Agent 會留在原處，請選擇另一台電腦。",
  "migration.error.transferSummaryInvalid": "來源電腦未能統計出這次遷移排除的檔案數。請將來源電腦上的 Raft Computer 更新到最新版本，然後重試。",
  "migration.error.userIgnoreWriteFailed": "無法在來源電腦上儲存你選擇排除的路徑，遷移已停止，沒有移動任何內容。",
  "migration.error.failedGeneric": "傳輸過程中發生錯誤。請再試一次。",
